import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>الصورة تعرض لحظة، وبيانات EXIF تروي القصة حول تلك اللحظة: أي كاميرا التقطتها ومتى وأين وبأي إعدادات.</p>\n<p>معظم الناس لا يرى هذه الطبقة أبدًا. تسافر بصمت داخل الملف، ناجية من النسخ وإعادة الإرسال والتنزيل حتى يزيلها شيء ما.</p>\n<p>يشرح هذا المقال EXIF بعمق: كيف يُبنى وما يكشفه كل حقل وكيف يتسرب، وكيف تقرأه وتزيله. دون حشو، فقط ما تحتويه البيانات فعلًا.</p>\n<h2 id=\"what-is-exif\">ما هو EXIF فعلًا</h2>\n<p>EXIF تعني صيغة ملف الصور القابلة للتبادل. إنها معيار لحفظ البيانات الوصفية داخل ملفات الصور، تكتبه الكاميرات والهواتف لحظة الالتقاط.</p>\n<p>تقنيًا، تعيش بيانات EXIF في بنية مبنية على TIFF ومضمّنة في الملف. في JPEG تكون في مقطع APP1، وفي PNG قد تكون في قطعة eXIf، وفي WebP في قطعة EXIF. والبنية مجموعة أدلة تسمى IFD، وكل IFD يحفظ وسومًا مرقمة، وكل وسم يحفظ قيمة: رقم أو سلسلة نصية أو عدد.</p>\n<h2 id=\"ifd0-device-identity\">IFD0: هوية جهازك</h2>\n<p>IFD0 هو الدليل الأول، وهو الذي يحدد الجهاز. ماركة الكاميرا وطرازها هما الحقلان الرئيسيان، لكن هناك المزيد.</p>\n<p>حقل البرنامج يسجل البرنامج الذي كتب الملف آخر مرة: قد يكون إصدار برنامج كاميرا ثابت أو نظام تشغيل هاتف أو تطبيق تحرير مثل Lightroom. وبعض الكاميرات تسجل هنا رقمًا تسلسليًا أو اسم مالك، وهذه الحقول تحوّل صورة مجهولة إلى صورة مرتبطة بجهاز محدد وأحيانًا بشخص محدد.</p>\n<h2 id=\"exififd-exposure-telemetry\">ExifIFD: قياسات التعريض</h2>\n<p>ExifIFD هو القلب التقني لـEXIF. يسجل قرارات التعريض التي اتخذتها الكاميرا، أو اتخذتها أنت، لحظة الالتقاط.</p>\n<p>ISO والفتحة وسرعة الغالق والبعد البؤري هي الحقول الأربعة التي تهم المصورين أكثر. معًا تصف الضوء وعمق المجال والحركة في اللقطة. وزمن التعريض يُحفظ ككسر نسبي مثل 1/250 ثانية، والفتحة تُحفظ كرقم F، والبعد البؤري يُحفظ بالملليمترات.</p>\n<h2 id=\"gpsifd-location\">GPSIFD: دليل الموقع</h2>\n<p>GPSIFD هو أصغر دليل وأخطرها. يحفظ خط العرض وخط الطول والارتفاع كأرقام نسبية بالدرجات والدقائق والثواني.</p>\n<p>العارض يحوّل تلك النسب إلى إحداثيات عشرية تلقائيًا. زوج مثل 25.2048، 55.2708 نقطة دقيقة على الخريطة، دقيقة بما يكفي لتحديد مبنى. ووسوم GPS تحمل أيضًا طابعًا زمنيًا ومرجع شمال أو جنوب وشرق أو غرب. والهواتف تسجل GPS افتراضيًا في معظم تطبيقات الكاميرا.</p>\n<h2 id=\"what-photos-reveal\">ما تكشفه صورك عنك</h2>\n<p>صورة واحدة تكشف قليلًا، ومجموعة صور تكشف كثيرًا. EXIF يحوّل مجموعة صور إلى خط زمني من الأماكن والروتين والأجهزة.</p>\n<p>طوابع زمنية للالتقاط في صور كثيرة تظهر متى تكون في المنزل ومتى تسافر ومتى تكون خارجًا عادة. وإحداثيات GPS في صور كثيرة ترسم خريطة منزلك وعملك وصالتك الرياضية ومدرسة أطفالك. وأرقام الكاميرا التسلسلية تربط صورًا بجهاز واحد، فإذا ظهر الرقم نفسه في صور بأسماء مختلفة، يصبح الارتباط بين تلك الهويات ظاهرًا.</p>\n<h2 id=\"how-exif-survives\">كيف ينجو EXIF وكيف يموت</h2>\n<p>ينجو EXIF من النسخ والإرسال بالبريد ونقل الملفات بين المجلدات. إنه جزء من الملف، فيسافر حيث يسافر الملف، ما لم يزله شيء بنشاط.</p>\n<p>الشبكات الاجتماعية وتطبيقات المراسلة هي المنظفات الكبرى. واتساب وإنستغرام وفيسبوك تزيل ترويسات EXIF والكاميرا وGPS تلقائيًا عند الرفع عبر خوادمها. ولهذا تظهر صورة منزّلة من إنستغرام صفر وسوم EXIF في عارض البيانات الوصفية: المنصة نظفتها لا أنت.</p>\n<h2 id=\"reading-exif\">كيف تقرأ بيانات EXIF</h2>\n<p>قراءة EXIF تتطلب عارضًا، لأن لا نظام تشغيل يعرض الصورة الكاملة افتراضيًا. <a href=\"/ar/arid-bayanat-as-sura/\">عارض بيانات الصورة</a> يحلل البايتات الخام محليًا ويجمع الحقول لك.</p>\n<p>ابدأ بإشعار الملخص. يخبرك بالصيغة والأبعاد وهل وُجدت أنواع وسوم حساسة. ثم راجع تنبيه GPS الذي يعرض الإحداثيات المفكوكة عند وجودها. وبعدها اقرأ الجدول المجمع: حقول الكاميرا تحدد الجهاز، وحقول EXIF تصف التعريض، وحقول GPS تعطي الموقع. وصدّر JSON عندما تحتاج سجلًا.</p>\n<h2 id=\"exif-vs-xmp-iptc\">EXIF مقابل XMP مقابل IPTC</h2>\n<p>EXIF ليس وحده. معياران آخران يشاركان الملف غالبًا، وكل منهما يكشف أشياء مختلفة.</p>\n<p>XMP حزمة XML من أدوبي مضمّنة في الملف. قد تحفظ سجل تحرير وتقييمات ووسومًا وأوصافًا. وصورة محررة في Lightroom أو فوتوشوب تحمل غالبًا سجل XMP طويلًا. أما IPTC فمعيار صحافة ونشر: يحفظ تعليقات وعناوين وكلمات مفتاحية واعتمادات ومعلومات حقوق نشر.</p>\n<h2 id=\"exif-and-orientation\">اتجاه EXIF: مشكلة الصورة الجانبية</h2>\n<p>وسم الاتجاه حقل EXIF صغير بأثر هائل. يخبر العارضين كيف يدورون صورة لتستقيم، لأن الكاميرات تحفظ البكسلات غالبًا في اتجاه واحد بغض النظر عن كيفية إمساك الكاميرا.</p>\n<p>عندما يُزال الوسم دون تدوير البكسلات، قد تظهر صورة عمودية جانبية. بيانات الصورة لا تتغير، لكن التعليمات التي جعلتها مستقيمة لم تعد موجودة. ولهذا تقدم أداة إزالة البيانات الوصفية طريقتين: التجريد الثنائي دون فقدان يزيل كتلة APP1، بما فيها وسم الاتجاه، دون لمس البكسلات.</p>\n<h2 id=\"exif-for-photographers\">EXIF للمصورين والمطورين</h2>\n<p>EXIF ليس مجرد خطر خصوصية. للمصورين أداة تعلم، وللمطورين عون في تصحيح الأخطاء.</p>\n<p>المصور يستطيع قراءة إعدادات تعريض لقطة رائعة وتكرارها. ISO والفتحة وسرعة الغالق والبعد البؤري معًا تشكل وصفة لتحقيق المظهر نفسه. والمطور يستطيع قراءة EXIF لشرح سلوك غريب: وسم اتجاه غير صحيح أو قيمة DPI غير متوقعة أو ملف ألوان مخفي يفسر غالبًا المشكلة.</p>\n<h2 id=\"removing-exif\">كيف تزيل EXIF بأمان</h2>\n<p>قراءة EXIF هي نصف العمل فقط. النصف الآخر هو إزالته قبل أن تصل صورة إلى أي مكان عام.</p>\n<p><a href=\"/ar/izala-bayanat-as-sura/\">أداة إزالة بيانات الصورة</a> تزيل EXIF وGPS وXMP وIPTC والتعليقات وقطع نص PNG محليًا في متصفحك. لا شيء يُرفع. والتجريد الثنائي دون فقدان يعمل على ملفات JPG وPNG، مزيلًا مقاطع البيانات الوصفية دون فك ترميز أو إعادة ضغط بكسل واحد. وبعد التنظيف، تحقق من النتيجة بإعادة سحب الملف النظيف إلى عارض البيانات الوصفية.</p>\n<h2 id=\"exif-myths\">خرافات شائعة عن EXIF</h2>\n<p>عدة خرافات عن EXIF تستمر، وكل منها يقود إلى إحساس زائف بالأمان. يجدر تصحيحها مباشرة.</p>\n<p>الخرافة الأولى: تغيير حجم صورة يزيل بياناتها الوصفية. تغيير الحجم يحافظ على EXIF عادة، ما لم تزله الأداة صراحة. والخرافة الثانية: التحويل بين الصيغ يزيل البيانات الوصفية. تحويل JPG إلى PNG قد يزيل EXIF، لكنه قد ينقله أيضًا في قطعة eXIf. والخرافة الثالثة: القص يزيل بيانات الموقع. القص يغيّر البكسلات لا الترويسات.</p>\n<h2 id=\"exif-explained-summary\">باختصار</h2>\n<p>EXIF هي البيانات المخفية التي تكتبها كاميرتك في كل صورة: هوية الجهاز وإعدادات التعريض وطوابع زمنية وإحداثيات GPS. تُنظم في أدلة IFD وتسافر مع الملف أينما ذهب.</p>\n<p>التطبيقات الاجتماعية تزيلها تلقائيًا، لكن المتاجر عبر الإنترنت والمنتديات والبريد غالبًا لا تفعل. ومجموعة صور قد تكشف روتينك وأماكنك وأجهزتك. اقرأ EXIF بعارض البيانات الوصفية وأزله بأداة إزالة البيانات الوصفية، وتحقق من الملف النظيف بإعادة فحصه.</p>\n<p>للخطوات التفصيلية، اقرأ <a href=\"/ar/blog/kayfiyya-ard-bayanat-as-sura/\">كيف تعرض بيانات الصورة</a> والدليل الكامل <a href=\"/ar/blog/dalil-arid-bayanat-as-suwar/\">عارض بيانات الصور: الدليل الكامل</a>. وللدليل الكامل للإزالة، اقرأ <a href=\"/ar/blog/dalil-izala-bayanat-as-suwar/\">إزالة بيانات الصورة: الدليل الكامل</a>، ولمخاطر الخصوصية وراء البيانات اقرأ <a href=\"/ar/blog/makhatir-khususiyyat-as-suwar-gps-exif/\">خصوصية الصور: مخاطر GPS وEXIF والبيانات الوصفية</a>. وللأبعاد وDPI، استخدم <a href=\"/ar/fahis-abad-as-sura/\">فاحص أبعاد الصورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكن استعادة بيانات EXIF بعد إزالتها؟","answer":"لا، فبعد إزالة مقاطع البيانات الوصفية من ملف تختفي المعلومات من تلك النسخة: لا يبقى شيء لاستعادته. ولهذا احفظ نسخة أصلية لنفسك قبل التنظيف إذا أردت الاحتفاظ بالبيانات."},{"question":"هل تؤثر بيانات EXIF في جودة الصورة أو حجم الملف؟","answer":"لا تغيّر EXIF مظهر البكسلات، لكنها تضيف إلى حجم الملف. صور الكاميرا تحمل غالبًا صورًا مصغرة للمعاينة مضمّنة وكتل XMP ومقاطع تعليقات قد تضيف عشرات الكيلوبايتات إلى كل ملف."},{"question":"هل كل الكاميرات والهواتف تكتب بيانات EXIF؟","answer":"تقريبًا كل الكاميرات الرقمية والهواتف الذكية تكتب بيانات EXIF افتراضيًا، بما فيها الماركة والطراز وإعدادات التعريض والطوابع الزمنية. وإحداثيات GPS تعتمد على تفعيل خدمات الموقع في تطبيق الكاميرا."},{"question":"هل تستطيع بيانات EXIF إثبات متى وأين التُقطت صورة؟","answer":"الطوابع الزمنية وإحداثيات GPS في EXIF دليل لا إثبات. الطوابع الزمنية يمكن تحريرها وبيانات GPS يمكن تزويرها والملف النظيف لا يحمل شيئًا. وللأغراض القانونية أو الصحفية، تحتاج إلى تأكيد مستقل."},{"question":"لماذا تعرض نسختان من الصورة نفسها بيانات EXIF مختلفة؟","answer":"كل نسخة مرت بمعالجة مختلفة. واحدة قد مرت بتطبيق اجتماعي أزال كل شيء، بينما بقيت الأخرى أصلية. التحرير والتحويل وإعادة التصدير قد تضيف حقولًا أو تغيّرها أو تزيلها، فـEXIF كل نسخة يعكس تاريخها."},{"question":"هل بيانات EXIF هي نفسها علامة مائية على الصورة؟","answer":"لا، العلامة المائية مرئية في البكسلات: شعار أو نص متراكب فوق الصورة. أما EXIF فبيانات ترويسة غير مرئية تصف الصورة. العلامة المائية تنجو من لقطات الشاشة وإعادة التصوير، بينما EXIF يُزال بسهولة."}];
